const staticData = $getWorkflowStaticData('global');
delete staticData.candidateSignal;
const row = $input.first().json;
return [{ json: {
  id: row.id,
  equity: row.equity,
  peakEquity: row.peakEquity,
  inPosition: !!row.inPosition,
  symbol: row.symbol,
  entryPrice: row.entryPrice,
  stopPrice: row.stopPrice,
  firstTarget: row.firstTarget,
  notionalFull: row.notionalFull,
  notionalRemaining: row.notionalRemaining,
  halfClosed: !!row.halfClosed,
  trailStop: row.trailStop,
  highestSinceEntry: row.highestSinceEntry,
  barsOpen: row.barsOpen,
  tradingLocked: !!row.tradingLocked
} }];

const state = $('Parse State').item.json;
const resp = $input.first().json;
const rows = resp.data || resp;
const parsed = rows.map(function(r){ const a = Array.isArray(r) ? r : Object.values(r); return { t:Number(a[0]), o:Number(a[1]), h:Number(a[2]), l:Number(a[3]), c:Number(a[4]), v:Number(a[5]) }; });
parsed.sort(function(a,b){ return a.t-b.t; });
function ema(values, period){ const k=2/(period+1); const out=[]; for (let i=0;i<values.length;i++){ out.push(i===0?values[i]:(values[i]*k+out[i-1]*(1-k))); } return out; }
function atrCalc(highs, lows, closes, period){ const trs=[]; for (let i=0;i<closes.length;i++){ if(i===0){trs.push(highs[i]-lows[i]); continue;} trs.push(Math.max(highs[i]-lows[i], Math.abs(highs[i]-closes[i-1]), Math.abs(lows[i]-closes[i-1]))); } const k=1/period; const out=[]; for (let i=0;i<trs.length;i++){ out.push(i===0?trs[i]:(trs[i]*k+out[i-1]*(1-k))); } return out; }
const closes = parsed.map(function(p){return p.c;});
const highs = parsed.map(function(p){return p.h;});
const lows = parsed.map(function(p){return p.l;});
const ema50 = ema(closes,50);
const ema200 = ema(closes,200);
const atr14 = atrCalc(highs,lows,closes,14);
const n = parsed.length;
const last = parsed[n-1];
const curAtr = atr14[n-1];
const deathCross = (ema50[n-2] >= ema200[n-2]) && (ema50[n-1] < ema200[n-1]);
const FEE_RATE = 0.001;
const TRAIL_ATR_MULT = 2.0;
const MAX_HOLD_BARS = 240;
let action = 'NONE';
let exitPrice = null;
let reason = null;
const su = Object.assign({}, state);
su.barsOpen = (state.barsOpen||0) + 1;
su.highestSinceEntry = Math.max(state.highestSinceEntry||state.entryPrice, last.h);
let trade = { closedAt: '', symbol: '', reason: '', entryPrice: 0, exitPrice: 0, notional: 0, grossPnl: 0, fees: 0, netPnl: 0, equityAfter: 0 };
let tradeHappened = false;
if (!state.halfClosed) {
  if (last.l <= state.stopPrice) { exitPrice = state.stopPrice; reason='STOP_FULL'; action='FULL_EXIT'; }
  else if (last.h >= state.firstTarget) {
    const half = state.notionalRemaining/2;
    const gross = (state.firstTarget-state.entryPrice)/state.entryPrice*half;
    const fees = half*FEE_RATE*2;
    const net = gross-fees;
    const newEquity = state.equity+net;
    su.equity = newEquity; su.peakEquity = Math.max(state.peakEquity, newEquity);
    su.notionalRemaining = half; su.halfClosed = true; su.stopPrice = state.entryPrice; su.trailStop = state.entryPrice;
    action='PARTIAL_EXIT'; reason='PARTIAL_TARGET'; exitPrice = state.firstTarget;
    trade = { closedAt: new Date().toISOString(), symbol: state.symbol, reason: reason, entryPrice: state.entryPrice, exitPrice: exitPrice, notional: half, grossPnl: gross, fees: fees, netPnl: net, equityAfter: newEquity }; tradeHappened = true;
  }
} else {
  const newTrail = last.h - TRAIL_ATR_MULT*curAtr;
  su.trailStop = Math.max(state.trailStop, state.stopPrice, newTrail);
  if (last.l <= su.trailStop) { exitPrice = su.trailStop; reason='TRAIL_STOP'; action='FULL_EXIT'; }
  else if (deathCross) { exitPrice = last.c; reason='TREND_INVALIDATION'; action='FULL_EXIT'; }
  else if (su.barsOpen >= MAX_HOLD_BARS) { exitPrice = last.c; reason='MAX_HOLD'; action='FULL_EXIT'; }
}
if (action === 'FULL_EXIT') {
  const notional = state.notionalRemaining;
  const gross = (exitPrice-state.entryPrice)/state.entryPrice*notional;
  const fees = notional*FEE_RATE*2;
  const net = gross-fees;
  const newEquity = state.equity+net;
  su.equity = newEquity; su.peakEquity = Math.max(state.peakEquity, newEquity);
  trade = { closedAt: new Date().toISOString(), symbol: state.symbol, reason: reason, entryPrice: state.entryPrice, exitPrice: exitPrice, notional: notional, grossPnl: gross, fees: fees, netPnl: net, equityAfter: newEquity }; tradeHappened = true;
  su.inPosition = false; su.symbol=''; su.entryPrice=0; su.stopPrice=0; su.firstTarget=0; su.notionalFull=0; su.notionalRemaining=0; su.halfClosed=false; su.trailStop=0; su.highestSinceEntry=0; su.barsOpen=0;
}
su.lastUpdated = new Date().toISOString();
return [{ json: { id: state.id, equity: su.equity, peakEquity: su.peakEquity, inPosition: su.inPosition, symbol: su.symbol, entryPrice: su.entryPrice, stopPrice: su.stopPrice, firstTarget: su.firstTarget, notionalFull: su.notionalFull, notionalRemaining: su.notionalRemaining, halfClosed: su.halfClosed, trailStop: su.trailStop, highestSinceEntry: su.highestSinceEntry, barsOpen: su.barsOpen, tradingLocked: state.tradingLocked, lastUpdated: su.lastUpdated, tradeOccurred: tradeHappened, trade: trade } }];

const staticData = $getWorkflowStaticData('global');
const cand = staticData.candidateSignal;
if (!cand) { return []; }
const state = $('Parse State').item.json;
const MIN_STOP_PCT = 0.03;
const RISK_PER_TRADE = 0.02;
const entry = cand.entryPrice;
const stop = entry - Math.max(1.5*cand.atr, MIN_STOP_PCT*entry);
const firstTarget = entry + 1.0*(entry-stop);
const riskAmount = state.equity * RISK_PER_TRADE;
const stopDistPct = (entry-stop)/entry;
const notional = Math.min(riskAmount/stopDistPct, state.equity*0.95);
delete staticData.candidateSignal;
return [{ json: { id: state.id, equity: state.equity, peakEquity: state.peakEquity, inPosition: true, symbol: cand.symbol, entryPrice: entry, stopPrice: stop, firstTarget: firstTarget, notionalFull: notional, notionalRemaining: notional, halfClosed: false, trailStop: 0, highestSinceEntry: entry, barsOpen: 0, tradingLocked: state.tradingLocked, lastUpdated: new Date().toISOString() } }];

const symbol = $('Symbol Scan Loop').item.json.symbol;
const resp = $input.first().json;
const rows = resp.data || resp;
if (!rows || rows.length < 210) { return [{ json: { symbol: symbol, signal: false, skipped: true } }]; }
const parsed = rows.map(function(r){ const a = Array.isArray(r) ? r : Object.values(r); return { t:Number(a[0]), o:Number(a[1]), h:Number(a[2]), l:Number(a[3]), c:Number(a[4]), v:Number(a[5]) }; });
parsed.sort(function(a,b){ return a.t-b.t; });
function ema(values, period){ const k=2/(period+1); const out=[]; for (let i=0;i<values.length;i++){ out.push(i===0?values[i]:(values[i]*k+out[i-1]*(1-k))); } return out; }
function atrCalc(highs, lows, closes, period){ const trs=[]; for (let i=0;i<closes.length;i++){ if(i===0){trs.push(highs[i]-lows[i]); continue;} trs.push(Math.max(highs[i]-lows[i], Math.abs(highs[i]-closes[i-1]), Math.abs(lows[i]-closes[i-1]))); } const k=1/period; const out=[]; for (let i=0;i<trs.length;i++){ out.push(i===0?trs[i]:(trs[i]*k+out[i-1]*(1-k))); } return out; }
function rsiCalc(closes, period){ const out=[]; let avgGain=0, avgLoss=0; for (let i=0;i<closes.length;i++){ if(i===0){out.push(50); continue;} const diff=closes[i]-closes[i-1]; const gain=diff>0?diff:0; const loss=diff<0?-diff:0; if(i===1){avgGain=gain; avgLoss=loss;} else {avgGain=(avgGain*(period-1)+gain)/period; avgLoss=(avgLoss*(period-1)+loss)/period;} const rs = avgLoss===0?100:avgGain/avgLoss; out.push(avgLoss===0?100:100-100/(1+rs)); } return out; }
const closes = parsed.map(function(p){return p.c;});
const highs = parsed.map(function(p){return p.h;});
const lows = parsed.map(function(p){return p.l;});
const vols = parsed.map(function(p){return p.v;});
const ema50 = ema(closes,50);
const ema200 = ema(closes,200);
const atr14 = atrCalc(highs,lows,closes,14);
const rsi14 = rsiCalc(closes,14);
const n = parsed.length;
const i = n-1;
let volSum = 0;
for (let j=Math.max(0,i-19); j<=i; j++){ volSum += vols[j]; }
const volAvg20 = volSum/20;
const uptrend = ema50[i] > ema200[i];
const prevRsi = rsi14[i-1];
const rsiCrossUp = prevRsi < 40 && rsi14[i] >= 40;
let hadPullback = false;
for (let j=Math.max(0,i-5); j<i; j++){ if (rsi14[j] < 40){ hadPullback = true; } }
const volOk = volAvg20 > 0 && (vols[i]/volAvg20) >= 1.2;
const volaOk = (atr14[i]/closes[i]) <= 0.05;
const signal = uptrend && rsiCrossUp && hadPullback && volOk && volaOk;
const staticData = $getWorkflowStaticData('global');
if (signal && !staticData.candidateSignal) { staticData.candidateSignal = { symbol: symbol, entryPrice: closes[i], atr: atr14[i] }; }
return [{ json: { symbol: symbol, signal: signal } }];
